phi * diff_y[t-1] + epsilon\nx = diff_y[:-1]  # lagged diff\ny_ar = diff_y[1:]  # current diff\n\n# OLS for phi\nphi = sum(x[i] * y_ar[i] for i in range(len(x))) / sum(x[i]**2 for i in range(len(x)))\nprint(f\"\\nAR(1) coefficient (phi): {phi:.6f}\")\n\n# Forecast for 1983 using ARIMA(1,1,0)\n# y_hat_1983 = y_1982 + phi * (y_1982 - y_1981)\nforecast_diff = phi * diff_y[-1]\nforecast_1983 = y[-1] + forecast_diff\n\nprint(f\"\\nLast observation (1982): {y[-1]}\")\nprint(f\"Last difference: {diff_y[-1]}\")\nprint(f\"Forecast difference: {forecast_diff:.4f}\")\nprint(f\"\\nForecast for March 31, 1983: {forecast_1983:.2f}\")\nprint(f\"Rounded forecast: {round(forecast_1983)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
